// UnitySynchronizationContext, simplified
public override void Post(SendOrPostCallback cb, object state)
{
    lock (_queue) _queue.Add((cb, state));          // from any thread
}

void ExecuteTasks()                                 // the player loop calls it once per frame
{
    lock (_queue) { _batch.AddRange(_queue); _queue.Clear(); }
    foreach (var (cb, state) in _batch) cb(state);  // on the main thread
    _batch.Clear();
}

