async Awaitable FlyAsync()
{
    await Awaitable.BackgroundThreadAsync();  // 1. from here: a pool thread
    var path = FindPath(map);                 // 2. heavy computation, frames keep going
    await Awaitable.MainThreadAsync();        // 3. back to the main thread
    for (int i = 0; i < path.Length; i++)
    {
        transform.position = path[i];         // 4. Unity API: allowed
        await Awaitable.NextFrameAsync();     // 5. one point per frame
    }
}

